import { type FormEvent, type ReactNode, createContext, useContext, useEffect, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { ArrowLeft, ArrowRight, Check, CircleAlert, Edit3, Filter, IndianRupee, Minus, PackagePlus, Plus, ReceiptText, Search, ShoppingCart, Sparkles, Trash2, Truck, UserRound, X, Users, CalendarClock } from 'lucide-react';
import { Link, Route, Switch, Router as WouterRouter, useLocation, useParams } from 'wouter';
import { InventoryShell } from '@/components/inventory-shell';
import { BrandMark, ProductImage, StatusPill } from '@/components/product-card';
import { brands, categories, Customer, EmiPayment, EmiPlan, money, Product, Purchase, readStore, Sale, seedProducts, statusOf, StockEntry, writeStore } from '@/lib/inventory';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const InventoryContext = createContext<ReturnType<typeof makeInventory> | null>(null);

function makeInventory() {
  const [products, setProducts] = useState<Product[]>(() => readStore('keystone-products', seedProducts));
  const [history, setHistory] = useState<StockEntry[]>(() => readStore('keystone-history', seedProducts.slice(0, 8).map((p, i) => ({ id:`seed-${i}`, productId:p.id, productName:p.name, type:'PURCHASE' as const, quantity:p.quantity, note:'Opening stock', date:p.createdAt }))));
  const [purchases, setPurchases] = useState<Purchase[]>(() => readStore('keystone-purchases', []));
  const [sales, setSales] = useState<Sale[]>(() => readStore('keystone-sales', []));
  const [customers, setCustomers] = useState<Customer[]>(() => readStore('keystone-customers', []));
  const [emiPlans, setEmiPlans] = useState<EmiPlan[]>(() => readStore('keystone-emi-plans', []));
  const [emiPayments, setEmiPayments] = useState<EmiPayment[]>(() => readStore('keystone-emi-payments', []));
  useEffect(() => writeStore('keystone-products', products), [products]);
  useEffect(() => writeStore('keystone-history', history), [history]);
  useEffect(() => writeStore('keystone-purchases', purchases), [purchases]);
  useEffect(() => writeStore('keystone-sales', sales), [sales]);
  useEffect(() => writeStore('keystone-customers', customers), [customers]);
  useEffect(() => writeStore('keystone-emi-plans', emiPlans), [emiPlans]);
  useEffect(() => writeStore('keystone-emi-payments', emiPayments), [emiPayments]);
  const adjustStock = (productId: string, amount: number, type: StockEntry['type'], note: string) => {
    const product = products.find(p => p.id === productId); if (!product || amount === 0 || product.quantity + amount < 0) return false;
    setProducts(prev => prev.map(p => p.id === productId ? { ...p, quantity: p.quantity + amount } : p));
    setHistory(prev => [{ id:`h-${Date.now()}-${Math.random()}`, productId, productName:product.name, type, quantity:Math.abs(amount), note, date:new Date().toISOString() }, ...prev]);
    return true;
  };
  const saveProduct = (data: Omit<Product, 'id'|'createdAt'>, id?: string) => id ? setProducts(prev => prev.map(p => p.id === id ? { ...p, ...data } : p)) : setProducts(prev => [{ ...data, id:`p-${Date.now()}`, createdAt:new Date().toISOString() }, ...prev]);
  const removeProduct = (productId: string) => { if (!products.some(p => p.id === productId)) return false; setProducts(prev => prev.filter(p => p.id !== productId)); return true; };
  const addPurchase = (data: Omit<Purchase, 'id'|'total'>) => { const total = data.quantity * data.purchasePrice; setPurchases(prev => [{ ...data, id:`pur-${Date.now()}`, total }, ...prev]); adjustStock(data.productId, data.quantity, 'PURCHASE', `Invoice ${data.invoice}`); };
  const upsertCustomer = (data: Omit<Customer, 'id'|'createdAt'>, id?: string) => { if (id) { setCustomers(prev => prev.map(c => c.id === id ? { ...c, ...data } : c)); return id; } const newId = `cus-${Date.now()}`; setCustomers(prev => [{ ...data, id:newId, createdAt:new Date().toISOString() }, ...prev]); return newId; };
  const addSale = (sale: Omit<Sale, 'id'|'date'>) => {
    if (sale.items.some(item => (products.find(p => p.id === item.productId)?.quantity ?? 0) < item.quantity)) return false;
    const purchaseCost = sale.items.reduce((sum, item) => sum + (products.find(p => p.id === item.productId)?.purchasePrice ?? 0) * item.quantity, 0);
    const profit = sale.total - purchaseCost;
    setSales(prev => [{ ...sale, id:`sale-${Date.now()}`, date:new Date().toISOString(), purchaseCost, profit, status:'COMPLETED' }, ...prev]);
    sale.items.forEach(item => adjustStock(item.productId, -item.quantity, 'SALE', `POS sale · ${sale.payment}`));
    return true;
  };
  const createEmiPlan = (data: Omit<EmiPlan,'id'|'paidInstallments'|'outstandingAmount'|'nextDueDate'|'status'>) => {
    const planId=`emi-${Date.now()}`; const start=new Date(data.startDate); const payments:EmiPayment[]=[];
    for(let i=1;i<=data.installments;i++){ const due=new Date(start); due.setMonth(due.getMonth()+i-1); payments.push({id:`emip-${Date.now()}-${i}`,emiPlanId:planId,installmentNumber:i,dueDate:due.toISOString(),amount:i===data.installments?Number((data.financedAmount-data.emiAmount*(data.installments-1)).toFixed(2)):data.emiAmount,status:'UPCOMING'}); }
    setEmiPlans(prev=>[{...data,id:planId,paidInstallments:0,outstandingAmount:data.financedAmount,nextDueDate:payments[0]?.dueDate??null,status:'ACTIVE'} ,...prev]);
    setEmiPayments(prev=>[...payments,...prev]); return planId;
  };
  const markEmiPaid = (paymentId:string) => {
    const payment=emiPayments.find(p=>p.id===paymentId); if(!payment || payment.status==='PAID') return false;
    setEmiPayments(prev=>prev.map(p=>p.id===paymentId?{...p,status:'PAID',paidDate:new Date().toISOString()}:p));
    setEmiPlans(prev=>prev.map(plan=>{ if(plan.id!==payment.emiPlanId)return plan; const paid=plan.paidInstallments+1; const outstanding=Math.max(0,plan.outstandingAmount-payment.amount); const next=emiPayments.find(p=>p.emiPlanId===plan.id&&p.status!=='PAID'&&p.id!==paymentId)?.dueDate??null; return {...plan,paidInstallments:paid,outstandingAmount:outstanding,nextDueDate:next,status:outstanding===0?'PAID':(next&&new Date(next)<new Date()?'OVERDUE':'ACTIVE')}; })); return true;
  };
  return { products, history, purchases, sales, customers, emiPlans, emiPayments, saveProduct, removeProduct, addPurchase, addSale, upsertCustomer, createEmiPlan, markEmiPaid, adjustStock };
}
function InventoryProvider({ children }: { children: ReactNode }) { return <InventoryContext.Provider value={makeInventory()}>{children}</InventoryContext.Provider>; }
function useInventory() { const ctx = useContext(InventoryContext); if (!ctx) throw new Error('Inventory provider missing'); return ctx; }

const inputClass = 'h-12 w-full rounded-full border border-[hsl(var(--input))] bg-[hsl(var(--card))] px-3.5 text-sm outline-none transition focus:border-[hsl(var(--primary))] focus:ring-2 focus:ring-[hsl(var(--primary)/.14)]';
const buttonPrimary = 'inline-flex items-center justify-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-4 py-2.5 text-sm font-semibold text-[hsl(var(--primary-foreground))] transition hover:-translate-y-0.5 hover:shadow-lg';
const buttonQuiet = 'inline-flex items-center justify-center gap-2 rounded-xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-4 py-2.5 text-sm font-semibold transition hover:bg-[hsl(var(--muted))]';
const pageKicker = 'font-mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--muted-foreground))]';
const dateLabel = (date: string) => new Date(date).toLocaleDateString('en-IN', { day:'2-digit', month:'short', year:'numeric' });
const moneyValue = (value:number) => new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',minimumFractionDigits:0,maximumFractionDigits:2}).format(value);

function PageTitle({ kicker, title, description, action }: { kicker:string; title:string; description?:string; action?:ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className={pageKicker}>{kicker}</p><h1 className="mt-2 text-3xl font-bold tracking-[-.045em] md:text-4xl">{title}</h1>{description&&<p className="mt-2 max-w-2xl text-sm text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>; }
function SearchField({ value,onChange,placeholder='Search products, brands or SKU' }:{value:string;onChange:(v:string)=>void;placeholder?:string}){return <div className="relative"><Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-[hsl(var(--muted-foreground))]"/><input data-testid="input-search" className={`${inputClass} pl-10`} value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/></div>}
function EmptyState({ icon:Icon=PackagePlus,title,description }:{icon?:typeof PackagePlus;title:string;description:string}){return <div className="flex min-h-52 flex-col items-center justify-center rounded-2xl border border-dashed border-[hsl(var(--border))] bg-[hsl(var(--card)/.55)] p-8 text-center"><Icon className="mb-3 h-7 w-7 text-[hsl(var(--muted-foreground))]"/><p className="font-semibold">{title}</p><p className="mt-1 max-w-md text-sm text-[hsl(var(--muted-foreground))]">{description}</p></div>}

function HomePage(){const {products,sales,emiPlans}=useInventory();const [,setLocation]=useLocation();const [search,setSearch]=useState('');const low=products.filter(p=>statusOf(p)==='LOW STOCK'),out=products.filter(p=>statusOf(p)==='OUT OF STOCK');const recent=[...products].sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,6);const filtered=search?products.filter(p=>`${p.name} ${p.brand} ${p.sku}`.toLowerCase().includes(search.toLowerCase())):[];const totalUnits=products.reduce((s,p)=>s+p.quantity,0);const stockValue=products.reduce((s,p)=>s+p.quantity*p.purchasePrice,0);const totalSales=sales.reduce((s,x)=>s+x.total,0);const totalProfit=sales.reduce((s,x)=>s+(x.profit??0),0);const outstanding=emiPlans.reduce((s,e)=>s+e.outstandingAmount,0);const compact=(v:number)=>v>=100000?`₹${(v/100000).toFixed(1)}L`:v>=1000?`₹${(v/1000).toFixed(1)}K`:moneyValue(v);const hour=new Date().getHours();const greeting=hour<12?'Good morning':hour<18?'Good afternoon':'Good evening';return <div className="mobile-page fade-up mx-auto"><div className="mb-6 flex items-start justify-between"><div><p className="text-[11px] font-medium text-[hsl(var(--muted-foreground))]">{new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'short'}).format(new Date())}</p><h1 className="mt-1 text-[25px] font-extrabold tracking-[-.055em]">{greeting}, Aarav</h1><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Here is your business at a glance.</p></div><div className="flex items-center gap-2"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[hsl(var(--accent))] text-xs font-bold">AM</span><button onClick={()=>setLocation('/customers?filter=overdue')} className="flex h-9 w-9 items-center justify-center rounded-full border border-[hsl(var(--border))] bg-[hsl(var(--card))]" aria-label="EMI alerts"><CircleAlert className="h-4 w-4"/></button></div></div><div className="relative mb-5"><SearchField value={search} onChange={setSearch} placeholder="Search products..."/>{search&&<div className="absolute top-14 z-20 w-full rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-2 shadow-xl">{filtered.length?filtered.slice(0,6).map(p=><button key={p.id} onClick={()=>setLocation(`/product/${p.id}`)} className="flex w-full items-center gap-3 rounded-xl p-2.5 text-left hover:bg-[hsl(var(--muted))]"><ProductImage product={p} className="h-11 w-11 rounded-lg"/><span className="min-w-0 flex-1"><strong className="block truncate text-sm">{p.name}</strong><small className="text-xs text-[hsl(var(--muted-foreground))]">{p.brand} · {p.sku}</small></span><ArrowRight className="h-4 w-4"/></button>):<p className="p-3 text-sm text-[hsl(var(--muted-foreground))]">No products found.</p>}</div>}</div><section className="mb-6"><div className="mb-3 flex items-end justify-between"><div><p className={pageKicker}>Business dashboard</p><h2 className="mt-1 text-[18px] font-extrabold tracking-[-.04em]">Today at a glance</h2></div><Link href="/sales" className="text-[11px] font-bold">Open sales</Link></div><div className="grid grid-cols-2 gap-3"><div className="dashboard-card relative overflow-hidden rounded-[22px] border border-[hsl(var(--border))] bg-[linear-gradient(145deg,hsl(247_32%_16%),hsl(247_27%_25%))] p-4 text-white shadow-[0_14px_30px_rgba(31,25,62,.16)]"><div className="pointer-events-none absolute -right-7 -top-7 h-24 w-24 rounded-full bg-white/10 blur-2xl"/><div className="relative"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-white/55">Total sales</p><p className="mt-3 text-[27px] font-extrabold tracking-[-.06em]">{compact(totalSales)}</p><p className="mt-1 text-[10px] text-white/55">{sales.length} completed sales</p></div></div><div className="dashboard-card relative overflow-hidden rounded-[22px] border border-[hsl(var(--border))] bg-[linear-gradient(145deg,hsl(164_30%_88%),hsl(164_28%_80%))] p-4 text-[hsl(165_28%_20%)] shadow-[0_14px_30px_rgba(38,99,88,.10)]"><div className="pointer-events-none absolute -right-7 -top-7 h-24 w-24 rounded-full bg-white/45 blur-2xl"/><p className="relative text-[10px] font-semibold uppercase tracking-[.14em] opacity-60">Total profit</p><p className="relative mt-3 text-[27px] font-extrabold tracking-[-.06em]">{compact(totalProfit)}</p><p className="relative mt-1 text-[10px] opacity-60">From completed sales</p></div><div className="rounded-[20px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-3.5 shadow-sm"><p className="text-[10px] text-[hsl(var(--muted-foreground))]">Stock value</p><p className="mt-2 text-[21px] font-extrabold tracking-[-.055em]">{compact(stockValue)}</p><p className="text-[9px] text-[hsl(var(--muted-foreground))]">at purchase cost</p></div><div className="rounded-[20px] border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-3.5 shadow-sm"><p className="text-[10px] text-[hsl(var(--muted-foreground))]">EMI outstanding</p><p className="mt-2 text-[21px] font-extrabold tracking-[-.055em]">{compact(outstanding)}</p><p className="text-[9px] text-[hsl(var(--muted-foreground))]">across active plans</p></div></div></section><div className="mb-7 grid grid-cols-2 gap-2.5 sm:grid-cols-3">{[['Low stock',low.length.toString(),'need attention'],['Out of stock',out.length.toString(),'currently empty'],['Catalog',products.length.toString(),'products listed']].map(([l,v,d])=><div key={l} className="rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] px-3 py-3.5"><p className="text-[10px] text-[hsl(var(--muted-foreground))]">{l}</p><p className="mt-2 text-[21px] font-extrabold tracking-[-.06em]">{v}</p><p className="text-[9px] text-[hsl(var(--muted-foreground))]">{d}</p></div>)}</div><section><div className="mb-3 flex items-end justify-between"><div><p className={pageKicker}>Shelf activity</p><h2 className="mt-1 text-[18px] font-extrabold">Recent products</h2></div><Link href="/inventory" className="text-[11px] font-bold">View all</Link></div><div className="space-y-2.5">{recent.map(product=><Link href={`/product/${product.id}`} key={product.id} className="flex items-center gap-3 rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-2.5 hover:shadow-md"><ProductImage product={product} className="h-[58px] w-[58px] shrink-0 rounded-[14px]"/><span className="min-w-0 flex-1"><strong className="block truncate text-[13px]">{product.name}</strong><span className="mt-1 block truncate text-[10px] text-[hsl(var(--muted-foreground))]">{product.brand} · {product.sku}</span><span className="mt-1.5 block text-[10px] font-semibold">{product.quantity} in stock</span></span><StatusPill product={product}/></Link>)}</div></section></div>}

function CustomersPage(){const {customers,sales,emiPlans}=useInventory();const [,setLocation]=useLocation();const [search,setSearch]=useState('');const [filter,setFilter]=useState('all');const today=new Date();const rows=customers.filter(c=>{const plans=emiPlans.filter(p=>p.customerId===c.id);const overdue=plans.some(p=>p.status==='OVERDUE'||(p.nextDueDate&&new Date(p.nextDueDate)<today&&p.outstandingAmount>0));const paid=plans.length>0&&plans.every(p=>p.status==='PAID');const text=`${c.name} ${c.phone}`.toLowerCase().includes(search.toLowerCase())||sales.some(s=>s.customerId===c.id&&s.invoice?.toLowerCase().includes(search.toLowerCase()));return text&&(filter==='all'||(filter==='active'&&plans.some(p=>p.status==='ACTIVE'))||(filter==='overdue'&&overdue)||(filter==='paid'&&paid));});return <div className="fade-up"><PageTitle kicker="People / Customers" title="Customers" description="Customers, purchases and EMI obligations in one place." action={<Link href="/customers/new" className={buttonPrimary}><Plus className="h-4 w-4"/>Add customer</Link>}/><div className="mb-4"><SearchField value={search} onChange={setSearch} placeholder="Search name, phone or invoice..."/></div><div className="mb-5 flex gap-2 overflow-x-auto">{[['all','All'],['active','EMI Active'],['overdue','EMI Overdue'],['paid','Fully Paid']].map(([k,l])=><button key={k} onClick={()=>setFilter(k)} className={`shrink-0 rounded-xl px-3.5 py-2.5 text-[11px] font-semibold ${filter===k?'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))]':'border border-[hsl(var(--border))] bg-[hsl(var(--card))]'}`}>{l}</button>)}</div>{rows.length?<div className="grid gap-3">{rows.map(c=>{const plans=emiPlans.filter(p=>p.customerId===c.id);const outstanding=plans.reduce((s,p)=>s+p.outstandingAmount,0);const next=plans.filter(p=>p.nextDueDate&&p.outstandingAmount>0).sort((a,b)=>String(a.nextDueDate).localeCompare(String(b.nextDueDate)))[0]?.nextDueDate;const total=sales.filter(s=>s.customerId===c.id).reduce((s,x)=>s+x.total,0);const overdue=plans.some(p=>p.status==='OVERDUE'||(p.nextDueDate&&new Date(p.nextDueDate)<today&&p.outstandingAmount>0));return <button key={c.id} onClick={()=>setLocation(`/customers/${c.id}`)} className="rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 text-left shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-start gap-3"><span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[hsl(var(--accent))] text-sm font-extrabold">{c.name.slice(0,1).toUpperCase()}</span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-3"><div><h3 className="truncate text-sm font-bold">{c.name}</h3><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">{c.phone}</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${overdue?'bg-red-50 text-red-600':outstanding?'bg-amber-50 text-amber-700':'bg-emerald-50 text-emerald-700'}`}>{overdue?'EMI Overdue':outstanding?'EMI Active':'Fully Paid'}</span></div><div className="mt-4 grid grid-cols-3 gap-3"><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Purchases</p><p className="mt-1 text-sm font-bold">{sales.filter(s=>s.customerId===c.id).length}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Spent</p><p className="mt-1 text-sm font-bold">{moneyValue(total)}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Outstanding</p><p className="mt-1 text-sm font-bold">{moneyValue(outstanding)}</p></div></div><p className="mt-3 text-[10px] text-[hsl(var(--muted-foreground))]">{next?`Next EMI · ${moneyValue(plans.find(p=>p.nextDueDate===next)?.emiAmount??0)} · ${dateLabel(next)}`:'No upcoming EMI'}</p></div></div></button>})}</div>:<EmptyState icon={Users} title="No customers yet" description="Add a customer from a sale or create one here."/>}</div>}

function CustomerFormPage(){const {customers,upsertCustomer}=useInventory();const {id}=useParams<{id:string}>();const existing=customers.find(c=>c.id===id);const [,setLocation]=useLocation();const [form,setForm]=useState({name:existing?.name||'',phone:existing?.phone||'',alternatePhone:existing?.alternatePhone||'',email:existing?.email||'',address:existing?.address||''});const save=(e:FormEvent)=>{e.preventDefault();const cid=upsertCustomer(form,id);setLocation(`/customers/${cid}`);};return <div className="fade-up"><Link href="/customers" className="mb-6 inline-flex items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]"><ArrowLeft className="h-4 w-4"/>Back to customers</Link><PageTitle kicker="People / Customer" title={existing?'Edit customer':'Add customer'} description="Keep contact details ready for every future sale and EMI."/><form onSubmit={save} className="max-w-2xl rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-semibold sm:col-span-2">Full name<input required className={`${inputClass} mt-2`} value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><label className="text-xs font-semibold">Mobile number<input required type="tel" className={`${inputClass} mt-2`} value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label><label className="text-xs font-semibold">Alternate number<input className={`${inputClass} mt-2`} value={form.alternatePhone} onChange={e=>setForm({...form,alternatePhone:e.target.value})}/></label><label className="text-xs font-semibold">Email<input type="email" className={`${inputClass} mt-2`} value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><label className="text-xs font-semibold sm:col-span-2">Address<textarea className="mt-2 min-h-28 w-full rounded-2xl border border-[hsl(var(--input))] bg-[hsl(var(--card))] p-3 text-sm outline-none focus:ring-2 focus:ring-[hsl(var(--primary)/.14)]" value={form.address} onChange={e=>setForm({...form,address:e.target.value})}/></label></div><div className="mt-6 flex justify-end"><button className={buttonPrimary}><Check className="h-4 w-4"/>Save customer</button></div></form></div>}

function CustomerDetailPage(){const {id}=useParams<{id:string}>();const {customers,sales,products,emiPlans,emiPayments,markEmiPaid}=useInventory();const customer=customers.find(c=>c.id===id);const [,setLocation]=useLocation();if(!customer)return <EmptyState icon={Users} title="Customer not found" description="This customer does not exist."/>;const csales=sales.filter(s=>s.customerId===id);const plans=emiPlans.filter(p=>p.customerId===id);const totalSpent=csales.reduce((s,x)=>s+x.total,0);const outstanding=plans.reduce((s,p)=>s+p.outstandingAmount,0);const next=plans.filter(p=>p.nextDueDate&&p.outstandingAmount>0).sort((a,b)=>String(a.nextDueDate).localeCompare(String(b.nextDueDate)))[0];return <div className="fade-up"><div className="flex items-start justify-between gap-4"><Link href="/customers" className="mb-6 inline-flex items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]"><ArrowLeft className="h-4 w-4"/>Back</Link><Link href={`/customers/${id}/edit`} className={buttonQuiet}><Edit3 className="h-4 w-4"/>Edit</Link></div><div className="rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 shadow-sm sm:p-7"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><span className="flex h-16 w-16 items-center justify-center rounded-3xl bg-[hsl(var(--accent))] text-xl font-extrabold">{customer.name.slice(0,1).toUpperCase()}</span><div className="min-w-0 flex-1"><p className={pageKicker}>Customer ID · {customer.id}</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.04em]">{customer.name}</h1><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{customer.phone}{customer.email?` · ${customer.email}`:''}</p></div><div className="grid grid-cols-3 gap-3 sm:min-w-[340px]"><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Purchases</p><p className="mt-1 text-lg font-extrabold">{csales.length}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Total spent</p><p className="mt-1 text-lg font-extrabold">{moneyValue(totalSpent)}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Outstanding</p><p className="mt-1 text-lg font-extrabold">{moneyValue(outstanding)}</p></div></div></div><p className="mt-5 text-xs text-[hsl(var(--muted-foreground))]">{customer.address||'No address saved.'}{customer.alternatePhone?` · Alternate ${customer.alternatePhone}`:''} · Added {dateLabel(customer.createdAt)}</p></div><section className="mt-8"><div className="mb-4 flex items-end justify-between"><div><p className={pageKicker}>Purchase history</p><h2 className="mt-1 text-xl font-bold">Everything purchased</h2></div><Link href="/sales" className="text-[11px] font-bold">New sale</Link></div><div className="space-y-3">{csales.length?csales.map(s=>s.items.map(item=>{const p=products.find(x=>x.id===item.productId);const final=item.price*item.quantity-(item.discount??0);return <div key={`${s.id}-${item.productId}`} className="flex items-center gap-3 rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-3"><ProductImage product={p??seedProducts[0]} className="h-16 w-16 shrink-0 rounded-xl"/><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{item.productName}</p><p className="mt-1 text-[10px] text-[hsl(var(--muted-foreground))]">{p?.brand} · {p?.model}{item.imei?` · IMEI ${item.imei}`:''}{item.serialNumber?` · SN ${item.serialNumber}`:''}</p><p className="mt-1 text-[10px] text-[hsl(var(--muted-foreground))]">{dateLabel(s.date)} · {s.invoice} · {s.payment}</p></div><div className="text-right"><p className="text-sm font-bold">{moneyValue(final)}</p><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Discount {moneyValue(item.discount??0)}</p></div></div>})):<EmptyState icon={ReceiptText} title="No purchases yet" description="Sales linked to this customer will appear here."/>}</div></section><section className="mt-8"><div className="mb-4"><p className={pageKicker}>EMI plans</p><h2 className="mt-1 text-xl font-bold">Installments</h2></div><div className="space-y-4">{plans.length?plans.map(plan=>{const payments=emiPayments.filter(p=>p.emiPlanId===plan.id).sort((a,b)=>a.installmentNumber-b.installmentNumber);return <div key={plan.id} className="rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="text-sm font-bold">{moneyValue(plan.totalAmount)} plan · {plan.installments} months</p><p className="mt-1 text-xs text-[hsl(var(--muted-foreground))]">Down payment {moneyValue(plan.downPayment)} · EMI {moneyValue(plan.emiAmount)} · {plan.frequency}</p></div><span className={`rounded-full px-2 py-1 text-[9px] font-bold ${plan.status==='PAID'?'bg-emerald-50 text-emerald-700':plan.status==='OVERDUE'?'bg-red-50 text-red-600':'bg-amber-50 text-amber-700'}`}>{plan.status}</span></div><div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4"><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Paid</p><p className="mt-1 font-bold">{plan.paidInstallments}/{plan.installments}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Outstanding</p><p className="mt-1 font-bold">{moneyValue(plan.outstandingAmount)}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">Start</p><p className="mt-1 font-bold">{dateLabel(plan.startDate)}</p></div><div><p className="text-[9px] text-[hsl(var(--muted-foreground))]">End</p><p className="mt-1 font-bold">{dateLabel(plan.endDate)}</p></div></div><div className="mt-5 space-y-2">{payments.map(payment=>{const overdue=payment.status!=='PAID'&&new Date(payment.dueDate)<new Date();const state=payment.status==='PAID'?'PAID':overdue?'OVERDUE':'UPCOMING';return <div key={payment.id} className="flex items-center gap-3 rounded-xl border border-[hsl(var(--border))] px-3 py-2.5"><span className={`flex h-7 w-7 items-center justify-center rounded-full text-[10px] font-bold ${state==='PAID'?'bg-emerald-100 text-emerald-700':state==='OVERDUE'?'bg-red-100 text-red-600':'bg-[hsl(var(--accent))]'}`}>{state==='PAID'?<Check className="h-3.5 w-3.5"/>:state==='OVERDUE'?'!':'·'}</span><span className="flex-1 text-xs"><strong>Installment {payment.installmentNumber}</strong><span className="ml-2 text-[hsl(var(--muted-foreground))]">{dateLabel(payment.dueDate)}</span></span><strong className="text-xs">{moneyValue(payment.amount)}</strong>{state!=='PAID'&&<button onClick={()=>markEmiPaid(payment.id)} className="rounded-lg bg-[hsl(var(--primary))] px-2.5 py-1.5 text-[10px] font-semibold text-[hsl(var(--primary-foreground))]">Mark paid</button>}</div>})}</div></div>}):<EmptyState icon={CalendarClock} title="No EMI plans" description="EMI plans created from sales will appear here."/>}</div></section></div>}

function SalesPage(){const {products,customers,upsertCustomer,addSale,createEmiPlan}=useInventory();const [search,setSearch]=useState('');const [cart,setCart]=useState<{productId:string;quantity:number}[]>([]);const [customerId,setCustomerId]=useState('');const [customerSearch,setCustomerSearch]=useState('');const [customerName,setCustomerName]=useState('');const [customerPhone,setCustomerPhone]=useState('');const [discountType,setDiscountType]=useState<'fixed'|'percent'>('fixed');const [discountValue,setDiscountValue]=useState('');const [payment,setPayment]=useState('Cash');const [cash,setCash]=useState('');const [upi,setUpi]=useState('');const [card,setCard]=useState('');const [downPayment,setDownPayment]=useState('');const [months,setMonths]=useState('6');const [firstDue,setFirstDue]=useState(new Date().toISOString().slice(0,10));const [invoice,setInvoice]=useState<Sale|null>(null);const results=products.filter(p=>p.quantity>0&&`${p.name} ${p.brand} ${p.sku}`.toLowerCase().includes(search.toLowerCase())).slice(0,10);const items=cart.map(i=>({...i,product:products.find(p=>p.id===i.productId)!})).filter(i=>i.product);const subtotal=items.reduce((s,i)=>s+i.product.sellingPrice*i.quantity,0);const rawDiscount=discountType==='percent'?subtotal*(Math.max(0,Math.min(100,Number(discountValue)||0))/100):Math.max(0,Number(discountValue)||0);const discount=Math.min(subtotal,rawDiscount);const total=Math.max(0,subtotal-discount);const purchaseCost=items.reduce((s,i)=>s+i.product.purchasePrice*i.quantity,0);const profit=total-purchaseCost;const margin=total?profit/total*100:0;const financed=Math.max(0,total-(Number(downPayment)||0));const emi=Number(months)>0?financed/Number(months):0;const paymentReceived=payment==='Mixed Payment'?Number(cash||0)+Number(upi||0)+Number(card||0):payment==='EMI'?Number(downPayment)||0:total;const canComplete=items.length>0&&payment==='EMI'?(customerId&&Number(downPayment)>=0&&Number(downPayment)<=total&&Number(months)>=1):items.length>0&&paymentReceived>=total;const add=(p:Product)=>setCart(prev=>prev.some(i=>i.productId===p.id)?prev.map(i=>i.productId===p.id?{...i,quantity:Math.min(p.quantity,i.quantity+1)}:i):[...prev,{productId:p.id,quantity:1}]);const remove=(id:string)=>setCart(prev=>prev.filter(i=>i.productId!==id));const dec=(id:string)=>setCart(prev=>prev.map(i=>i.productId===id?{...i,quantity:i.quantity-1}:i).filter(i=>i.quantity>0));const selectCustomer=(c:Customer)=>{setCustomerId(c.id);setCustomerName(c.name);setCustomerPhone(c.phone);};const finish=()=>{if(!canComplete)return;let cid=customerId;if(!cid&&customerName.trim()&&customerPhone.trim())cid=upsertCustomer({name:customerName.trim(),phone:customerPhone.trim()});if(payment==='EMI'&&!cid)return;const sale:{invoice:string;customerId?:string;customerName?:string;items:{productId:string;productName:string;quantity:number;price:number;discount?:number}[];subtotal:number;discount:number;total:number;payment:string;discountType:'fixed'|'percent';discountValue:number}={invoice:`INV-${new Date().getFullYear()}-${String(Date.now()).slice(-6)}`,customerId:cid||undefined,customerName:customerName.trim()||undefined,items:items.map(i=>({productId:i.productId,productName:i.product.name,quantity:i.quantity,price:i.product.sellingPrice,discount:discount*(i.product.sellingPrice*i.quantity/subtotal)})),subtotal,discount,total,payment,discountType,discountValue:Number(discountValue)||0};if(addSale(sale)){const created:Sale={...sale,id:`sale-${Date.now()}`,date:new Date().toISOString(),purchaseCost,profit,status:'COMPLETED'};if(payment==='EMI'&&cid){const start=new Date(firstDue);const end=new Date(start);end.setMonth(end.getMonth()+Number(months)-1);createEmiPlan({saleId:created.id,customerId:cid,totalAmount:total,downPayment:Number(downPayment)||0,financedAmount:financed,emiAmount:emi,installments:Number(months),startDate:firstDue,endDate:end.toISOString(),frequency:'MONTHLY'});}setInvoice(created);setCart([]);setDiscountValue('');setCustomerId('');setCustomerName('');setCustomerPhone('');}};return <div className="fade-up pb-24"><PageTitle kicker="Flow / Point of sale" title="Sales" description="A fast, premium checkout built for a real electronics counter." action={<div className="rounded-full bg-[hsl(var(--accent))] px-4 py-2 text-xs font-semibold">{cart.reduce((s,i)=>s+i.quantity,0)} items</div>}/><div className="grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><section className="min-w-0 rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-4 sm:p-6"><div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div><p className={pageKicker}>Select items</p><h2 className="mt-1 text-xl font-bold">Product shelf</h2></div><div className="w-full sm:w-80"><SearchField value={search} onChange={setSearch} placeholder="Search or scan product..."/></div></div><div className="grid gap-3 sm:grid-cols-2">{results.map(p=><button key={p.id} onClick={()=>add(p)} className="flex min-w-0 items-center gap-3 rounded-2xl border border-[hsl(var(--border))] p-3 text-left transition hover:-translate-y-0.5 hover:shadow-md"><ProductImage product={p} className="h-20 w-20 shrink-0 rounded-xl"/><span className="min-w-0 flex-1"><span className="flex items-center gap-2"><BrandMark brand={p.brand} size="sm"/><strong className="truncate text-sm">{p.name}</strong></span><small className="mt-2 block text-xs text-[hsl(var(--muted-foreground))]">{moneyValue(p.sellingPrice)} · {p.quantity} available</small></span><Plus className="h-5 w-5 shrink-0"/></button>)}</div></section><aside className="min-w-0 rounded-3xl bg-[hsl(var(--primary))] p-4 text-[hsl(var(--primary-foreground))] shadow-xl sm:p-6 lg:sticky lg:top-20 lg:h-fit"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] uppercase tracking-[.18em] opacity-50">Current sale</p><h2 className="mt-1 text-xl font-bold">Checkout</h2></div><ShoppingCart className="h-5 w-5 text-[hsl(var(--secondary))]"/></div><div className="mt-5 space-y-2">{items.length?items.map(i=><div key={i.productId} className="rounded-xl bg-[hsl(var(--primary-foreground)/.06)] p-2.5"><div className="flex items-center gap-2"><ProductImage product={i.product} className="h-11 w-11 rounded-lg"/><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{i.product.name}</p><p className="text-[11px] opacity-50">{moneyValue(i.product.sellingPrice)} each</p></div><button onClick={()=>remove(i.productId)} className="rounded-lg p-1.5 opacity-55 hover:opacity-100" aria-label={`Remove ${i.product.name}`}><Trash2 className="h-4 w-4"/></button></div><div className="mt-2 flex items-center justify-between"><span className="text-[11px] opacity-55">Qty</span><div className="flex items-center gap-2 rounded-lg bg-[hsl(var(--primary-foreground)/.1)] p-1"><button onClick={()=>dec(i.productId)} className="rounded-md p-1"><Minus className="h-3 w-3"/></button><span className="w-5 text-center text-xs font-bold">{i.quantity}</span><button onClick={()=>add(i.product)} className="rounded-md p-1"><Plus className="h-3 w-3"/></button></div><strong className="text-sm">{moneyValue(i.product.sellingPrice*i.quantity)}</strong></div></div>):<p className="py-12 text-center text-sm opacity-45">Add a product to begin.</p>}</div><div className="mt-4 border-t border-[hsl(var(--primary-foreground)/.12)] pt-4"><div className="flex items-center justify-between"><span className="text-xs opacity-55">Customer</span><span className="text-[10px] opacity-40">Optional for normal sales</span></div><div className="mt-2 space-y-2"><select value={customerId} onChange={e=>{const c=customers.find(x=>x.id===e.target.value);if(c)selectCustomer(c);else setCustomerId('')}} className="h-10 w-full rounded-xl bg-[hsl(var(--primary-foreground)/.08)] px-3 text-xs text-[hsl(var(--primary-foreground))] outline-none"><option value="">Select existing customer</option>{customers.map(c=><option key={c.id} value={c.id}>{c.name} · {c.phone}</option>)}</select>{!customerId&&<div className="grid grid-cols-2 gap-2"><input value={customerName} onChange={e=>setCustomerName(e.target.value)} placeholder="Customer name" className="h-10 min-w-0 rounded-xl bg-[hsl(var(--primary-foreground)/.08)] px-3 text-xs text-white outline-none placeholder:opacity-35"/><input value={customerPhone} onChange={e=>setCustomerPhone(e.target.value)} placeholder="Mobile" className="h-10 min-w-0 rounded-xl bg-[hsl(var(--primary-foreground)/.08)] px-3 text-xs text-white outline-none placeholder:opacity-35"/></div>}</div><div className="mt-4 flex items-center justify-between gap-2"><div className="flex rounded-xl bg-[hsl(var(--primary-foreground)/.08)] p-1"><button onClick={()=>setDiscountType('fixed')} className={`rounded-lg px-3 py-1.5 text-[10px] font-bold ${discountType==='fixed'?'bg-white/15':''}`}>₹</button><button onClick={()=>setDiscountType('percent')} className={`rounded-lg px-3 py-1.5 text-[10px] font-bold ${discountType==='percent'?'bg-white/15':''}`}>%</button></div><input type="number" min="0" max={discountType==='percent'?100:subtotal} value={discountValue} onChange={e=>setDiscountValue(e.target.value)} placeholder="Discount" className="h-10 w-32 rounded-xl bg-[hsl(var(--primary-foreground)/.08)] px-3 text-right text-xs text-white outline-none"/></div>{discount>0&&<div className="mt-2 flex items-center gap-2 text-[10px] font-semibold text-emerald-200"><Sparkles className="h-3.5 w-3.5"/>You saved {moneyValue(discount)}</div>}<div className="mt-4 space-y-1.5 text-sm"><div className="flex justify-between opacity-55"><span>Subtotal</span><span>{moneyValue(subtotal)}</span></div><div className="flex justify-between opacity-70"><span>Discount</span><span>-{moneyValue(discount)}</span></div><div className="mt-3 flex items-end justify-between border-t border-[hsl(var(--primary-foreground)/.12)] pt-3"><span className="text-xs opacity-55">Final total</span><strong className="text-3xl tracking-[-.05em]">{moneyValue(total)}</strong></div><div className="grid grid-cols-3 gap-2 pt-2 text-[10px] opacity-65"><span>Cost {moneyValue(purchaseCost)}</span><span>Profit {moneyValue(profit)}</span><span>Margin {margin.toFixed(1)}%</span></div></div><p className="mt-5 font-mono text-[10px] uppercase tracking-wider opacity-45">Payment</p><div className="mt-2 grid grid-cols-3 gap-1.5 sm:grid-cols-6">{['Cash','UPI','Card','Bank Transfer','EMI','Mixed Payment'].map(method=><button key={method} onClick={()=>setPayment(method)} className={`rounded-lg px-1 py-2 text-[9px] font-semibold ${payment===method?'bg-[hsl(var(--secondary))] text-[hsl(var(--secondary-foreground))]':'bg-[hsl(var(--primary-foreground)/.1)]'}`}>{method}</button>)}</div>{payment==='Mixed Payment'&&<div className="mt-3 grid grid-cols-3 gap-2"><input type="number" value={cash} onChange={e=>setCash(e.target.value)} placeholder="Cash" className="h-9 rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/><input type="number" value={upi} onChange={e=>setUpi(e.target.value)} placeholder="UPI" className="h-9 rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/><input type="number" value={card} onChange={e=>setCard(e.target.value)} placeholder="Card" className="h-9 rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/></div>}{payment==='EMI'&&<div className="mt-3 grid gap-2 sm:grid-cols-3"><div><label className="text-[9px] opacity-55">Down payment</label><input type="number" min="0" max={total} value={downPayment} onChange={e=>setDownPayment(e.target.value)} className="mt-1 h-9 w-full rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/></div><div><label className="text-[9px] opacity-55">Months</label><input type="number" min="1" value={months} onChange={e=>setMonths(e.target.value)} className="mt-1 h-9 w-full rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/></div><div><label className="text-[9px] opacity-55">First EMI date</label><input type="date" value={firstDue} onChange={e=>setFirstDue(e.target.value)} className="mt-1 h-9 w-full rounded-lg bg-white/10 px-2 text-xs text-white outline-none"/></div><p className="text-[10px] sm:col-span-3">Finance {moneyValue(financed)} · EMI {moneyValue(emi)} / month</p></div>}<button disabled={!canComplete} onClick={finish} className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-[hsl(var(--secondary))] px-4 py-3.5 text-sm font-bold text-[hsl(var(--secondary-foreground))] disabled:cursor-not-allowed disabled:opacity-40"><ReceiptText className="h-4 w-4"/>Complete sale</button></div></aside></div>{invoice&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 p-4"><div className="w-full max-w-md rounded-3xl bg-[hsl(var(--card))] p-6 shadow-2xl"><button className="float-right" onClick={()=>setInvoice(null)} aria-label="Close"><X className="h-5 w-5"/></button><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[hsl(var(--accent))]"><Check className="h-5 w-5"/></span><h2 className="mt-4 text-xl font-bold">Sale completed</h2><p className="mt-1 text-sm text-[hsl(var(--muted-foreground))]">{invoice.invoice}</p><div className="mt-5 rounded-2xl bg-[hsl(var(--muted)/.55)] p-4"><div className="flex justify-between text-sm"><span>Final amount</span><strong>{moneyValue(invoice.total)}</strong></div><div className="mt-2 flex justify-between text-sm"><span>Discount</span><strong>-{moneyValue(invoice.discount)}</strong></div><div className="mt-2 flex justify-between text-sm"><span>Profit</span><strong>{moneyValue(invoice.profit??0)}</strong></div><div className="mt-2 flex justify-between text-sm"><span>Customer</span><strong>{invoice.customerName||'Walk-in'}</strong></div></div><div className="mt-5 flex gap-2"><Link href="/sales" className={`${buttonPrimary} flex-1`} onClick={()=>setInvoice(null)}>New sale</Link>{invoice.customerId&&<Link href={`/customers/${invoice.customerId}`} className={`${buttonQuiet} flex-1`} onClick={()=>setInvoice(null)}>View customer</Link>}</div></div></div>}</div>}

function InventoryPage(){const {products}=useInventory();const [location,setLocation]=useLocation();const params=new URLSearchParams(location.split('?')[1]||'');const [search,setSearch]=useState('');const [category,setCategory]=useState(params.get('category')||'');const [brand,setBrand]=useState(params.get('brand')||'');const [status,setStatus]=useState(params.get('status')||'');const [sort,setSort]=useState('newest');const [removeTarget,setRemoveTarget]=useState<Product|null>(null);useEffect(()=>{const p=new URLSearchParams(location.split('?')[1]||'');setCategory(p.get('category')||'');setBrand(p.get('brand')||'');setStatus(p.get('status')||'')},[location]);const filtered=useMemo(()=>products.filter(p=>(!search||`${p.name} ${p.brand} ${p.sku} ${p.model}`.toLowerCase().includes(search.toLowerCase()))&&(!category||p.category===category)&&(!brand||p.brand===brand)&&(!status||statusOf(p)===status)).sort((a,b)=>sort==='price'?b.sellingPrice-a.sellingPrice:sort==='stock'?a.quantity-b.quantity:b.createdAt.localeCompare(a.createdAt)),[products,search,category,brand,status,sort]);return <div className="mx-auto max-w-6xl fade-up"><PageTitle kicker={`Catalog / ${products.length} products`} title="Inventory" description="A clean marketplace-style shelf for your store." action={<Link href="/inventory/new" className={`${buttonPrimary} shrink-0`}><Plus className="h-4 w-4"/>Add product</Link>}/><div className="mb-3"><SearchField value={search} onChange={setSearch}/></div><div className="mb-4 flex gap-2 overflow-x-auto"><select className="h-9 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-2.5 text-[10px] font-semibold" value={category} onChange={e=>setCategory(e.target.value)}><option value="">All categories</option>{categories.map(c=><option key={c}>{c}</option>)}</select><select className="h-9 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-2.5 text-[10px] font-semibold" value={brand} onChange={e=>setBrand(e.target.value)}><option value="">All brands</option>{brands.map(b=><option key={b}>{b}</option>)}</select><select className="h-9 rounded-lg border border-[hsl(var(--border))] bg-[hsl(var(--card))] px-2.5 text-[10px] font-semibold" value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="price">Price high to low</option><option value="stock">Stock low to high</option></select></div>{filtered.length?<div className="grid gap-3">{filtered.map(p=><div key={p.id} className="flex items-center gap-3 rounded-2xl border border-[hsl(var(--card-border))] bg-[hsl(var(--card))] p-2.5 shadow-sm"><Link href={`/product/${p.id}`} className="flex min-w-0 flex-1 items-center gap-3"><ProductImage product={p} className="h-[60px] w-[60px] shrink-0 rounded-[14px]"/><span className="min-w-0 flex-1"><span className="mb-1 flex items-center gap-2"><BrandMark brand={p.brand} size="sm"/><span className="truncate text-[9px] font-bold uppercase tracking-[.11em] text-[hsl(var(--muted-foreground))]">{p.brand}</span></span><strong className="block truncate text-[13px]">{p.name}</strong><span className="mt-1 block truncate font-mono text-[9px] text-[hsl(var(--muted-foreground))]">SKU {p.sku} · {p.model}</span><span className="mt-1.5 block text-[10px] font-semibold">{p.quantity} in stock · {moneyValue(p.sellingPrice)}</span></span><StatusPill product={p}/></Link><button onClick={()=>setRemoveTarget(p)} className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl text-[hsl(var(--muted-foreground))] hover:bg-red-50 hover:text-[hsl(var(--destructive))]" title="Remove product" aria-label={`Remove ${p.name}`}><Trash2 className="h-4 w-4"/></button></div>)}</div>:<EmptyState icon={Filter} title="Nothing matches" description="Try another filter or search term."/>}{removeTarget&&<div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 p-4"><div className="w-full max-w-sm rounded-3xl bg-[hsl(var(--card))] p-5 shadow-2xl"><span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-red-50 text-red-600"><Trash2 className="h-5 w-5"/></span><h2 className="mt-4 text-lg font-extrabold">Remove {removeTarget.name}?</h2><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">The product will disappear from active inventory. Existing transaction history is retained.</p><div className="mt-5 flex gap-2"><button className={`${buttonQuiet} flex-1`} onClick={()=>setRemoveTarget(null)}>Keep</button><button className="flex-1 rounded-xl bg-[hsl(var(--destructive))] px-4 py-2.5 text-sm font-semibold text-white" onClick={()=>{useInventory().removeProduct(removeTarget.id);setRemoveTarget(null)}}>Remove</button></div></div></div>}</div>}

function ProductFormPage(){const {id}=useParams<{id:string}>();const {products,saveProduct}=useInventory();const [,setLocation]=useLocation();const existing=products.find(p=>p.id===id);const [form,setForm]=useState({name:existing?.name||'',brand:existing?.brand||'',category:existing?.category||'Mobile',model:existing?.model||'',sku:existing?.sku||'',purchasePrice:String(existing?.purchasePrice||''),sellingPrice:String(existing?.sellingPrice||''),mrp:String(existing?.mrp||''),quantity:String(existing?.quantity??''),minStock:String(existing?.minStock??2),warranty:existing?.warranty||'1 Year',image:existing?.image||''});const update=(k:keyof typeof form,v:string)=>setForm(x=>({...x,[k]:v}));const submit=(e:FormEvent)=>{e.preventDefault();saveProduct({name:form.name,brand:form.brand,category:form.category as Product['category'],model:form.model,sku:form.sku,purchasePrice:Number(form.purchasePrice),sellingPrice:Number(form.sellingPrice),mrp:Number(form.mrp),quantity:Number(form.quantity),minStock:Number(form.minStock),warranty:form.warranty,image:form.image||seedProducts[0].image},id);setLocation(id?`/product/${id}`:'/inventory')};return <div className="fade-up"><PageTitle kicker={id?'Catalog / Edit product':'Catalog / New product'} title={id?'Refine product':'Add a product'} description="Keep the product image, model and pricing precise."/><form onSubmit={submit} className="max-w-3xl rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-7"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-semibold sm:col-span-2">Product name<input required className={`${inputClass} mt-2`} value={form.name} onChange={e=>update('name',e.target.value)}/></label><label className="text-xs font-semibold">Brand<select required className={`${inputClass} mt-2`} value={form.brand} onChange={e=>update('brand',e.target.value)}><option value="">Select</option>{brands.map(b=><option key={b}>{b}</option>)}</select></label><label className="text-xs font-semibold">Category<select className={`${inputClass} mt-2`} value={form.category} onChange={e=>update('category',e.target.value)}>{categories.map(c=><option key={c}>{c}</option>)}</select></label><label className="text-xs font-semibold">Model<input required className={`${inputClass} mt-2`} value={form.model} onChange={e=>update('model',e.target.value)}/></label><label className="text-xs font-semibold">SKU<input required className={`${inputClass} mt-2 font-mono`} value={form.sku} onChange={e=>update('sku',e.target.value)}/></label><label className="text-xs font-semibold">Purchase price<input required type="number" className={`${inputClass} mt-2`} value={form.purchasePrice} onChange={e=>update('purchasePrice',e.target.value)}/></label><label className="text-xs font-semibold">Selling price<input required type="number" className={`${inputClass} mt-2`} value={form.sellingPrice} onChange={e=>update('sellingPrice',e.target.value)}/></label><label className="text-xs font-semibold">MRP<input required type="number" className={`${inputClass} mt-2`} value={form.mrp} onChange={e=>update('mrp',e.target.value)}/></label><label className="text-xs font-semibold">Quantity<input required type="number" className={`${inputClass} mt-2`} value={form.quantity} onChange={e=>update('quantity',e.target.value)}/></label><label className="text-xs font-semibold">Minimum stock<input required type="number" className={`${inputClass} mt-2`} value={form.minStock} onChange={e=>update('minStock',e.target.value)}/></label><label className="text-xs font-semibold">Warranty<select className={`${inputClass} mt-2`} value={form.warranty} onChange={e=>update('warranty',e.target.value)}><option>6 Months</option><option>1 Year</option><option>2 Years</option><option>5 Years</option><option>10 Years</option></select></label><label className="text-xs font-semibold sm:col-span-2">Product image URL<input className={`${inputClass} mt-2`} value={form.image} onChange={e=>update('image',e.target.value)}/></label></div><div className="mt-6 flex justify-end"><button className={buttonPrimary}><Check className="h-4 w-4"/>{id?'Save changes':'Add product'}</button></div></form></div>}

function HistoryPage(){const {history}=useInventory();const [filter,setFilter]=useState('ALL');const rows=filter==='ALL'?history:history.filter(h=>h.type===filter);return <div className="fade-up"><PageTitle kicker="Manage / Ledger" title="Stock history" description="Every movement in one reliable trail." action={<div className="flex gap-2">{['ALL','PURCHASE','SALE'].map(v=><button key={v} onClick={()=>setFilter(v)} className={`rounded-full px-3 py-2 text-[10px] font-bold ${filter===v?'bg-[hsl(var(--primary))] text-white':'border border-[hsl(var(--border))]'}`}>{v}</button>)}</div>}/><div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">{rows.map(r=><div key={r.id} className="grid gap-1 border-b border-[hsl(var(--border))] px-5 py-4 sm:grid-cols-[1.3fr_1fr_.6fr_1.5fr_1fr]"><span className="text-sm font-semibold">{r.productName}</span><span className="text-xs font-bold">{r.type}</span><span className="font-mono text-sm">{r.type==='SALE'?'-':'+'}{r.quantity}</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{r.note}</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{dateLabel(r.date)}</span></div>)}</div></div>}
function PurchasesPage(){const {purchases}=useInventory();return <div className="fade-up"><PageTitle kicker="Flow / Incoming" title="Purchases" description="Restock the catalog and keep incoming goods visible." action={<Link href="/purchases/new" className={buttonPrimary}><Plus className="h-4 w-4"/>New purchase</Link>}/>{purchases.length?<div className="overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">{purchases.map(p=><div key={p.id} className="grid gap-1 border-b px-5 py-4 sm:grid-cols-[1.2fr_1fr_1fr_.7fr_1fr]"><span className="text-sm font-semibold">{p.productName}</span><span className="text-sm">{p.supplier}</span><span className="font-mono text-xs">{p.invoice}</span><span>{p.quantity}</span><span className="font-semibold">{moneyValue(p.total)}</span></div>)}</div>:<EmptyState icon={Truck} title="No purchases yet" description="Record your next delivery."/>}</div>}
function PurchaseFormPage(){const {products,addPurchase}=useInventory();const [,setLocation]=useLocation();const [productId,setProductId]=useState(products[0]?.id||'');const product=products.find(p=>p.id===productId);const [f,setF]=useState({supplier:'',invoice:'',date:new Date().toISOString().slice(0,10),quantity:'1',purchasePrice:String(product?.purchasePrice||'')});useEffect(()=>{if(product)setF(x=>({...x,purchasePrice:String(product.purchasePrice)}))},[productId]);return <div className="fade-up"><PageTitle kicker="Flow / Incoming" title="New purchase" description="One entry adds the delivery to the ledger and shelf."/><form onSubmit={e=>{e.preventDefault();if(product){addPurchase({supplier:f.supplier,invoice:f.invoice,date:f.date,productId,productName:product.name,quantity:Number(f.quantity),purchasePrice:Number(f.purchasePrice)});setLocation('/purchases')}}} className="max-w-2xl rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))] p-5 sm:p-8"><div className="grid gap-5 sm:grid-cols-2"><label className="text-xs font-semibold">Supplier<input required className={`${inputClass} mt-2`} value={f.supplier} onChange={e=>setF({...f,supplier:e.target.value})}/></label><label className="text-xs font-semibold">Invoice<input required className={`${inputClass} mt-2`} value={f.invoice} onChange={e=>setF({...f,invoice:e.target.value})}/></label><label className="text-xs font-semibold sm:col-span-2">Product<select className={`${inputClass} mt-2`} value={productId} onChange={e=>setProductId(e.target.value)}>{products.map(p=><option key={p.id} value={p.id}>{p.name} · {p.sku}</option>)}</select></label><label className="text-xs font-semibold">Quantity<input required type="number" min="1" className={`${inputClass} mt-2`} value={f.quantity} onChange={e=>setF({...f,quantity:e.target.value})}/></label><label className="text-xs font-semibold">Purchase price<input required type="number" min="0" className={`${inputClass} mt-2`} value={f.purchasePrice} onChange={e=>setF({...f,purchasePrice:e.target.value})}/></label></div><div className="mt-6 flex justify-end"><button className={buttonPrimary}>Save purchase</button></div></form></div>}

function ProductDetailScreen(){const {id}=useParams<{id:string}>();const {products,history}=useInventory();const p=products.find(x=>x.id===id);if(!p)return <EmptyState title="Product not found" description="This product may have been removed."/>;return <div className="fade-up"><Link href="/inventory" className="mb-6 inline-flex items-center gap-2 text-xs font-semibold text-[hsl(var(--muted-foreground))]"><ArrowLeft className="h-4 w-4"/>Back to inventory</Link><div className="grid gap-8 lg:grid-cols-[1.05fr_.95fr]"><div className="overflow-hidden rounded-3xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]"><ProductImage product={p} className="aspect-square w-full lg:min-h-[560px]"/></div><div><div className="flex items-start justify-between gap-3"><div><div className="flex items-center gap-2"><BrandMark brand={p.brand} size="sm"/><p className={pageKicker}>{p.brand} / {p.category}</p></div><h1 className="mt-3 text-3xl font-bold tracking-[-.05em]">{p.name}</h1><p className="mt-2 font-mono text-xs text-[hsl(var(--muted-foreground))]">{p.model} · {p.sku}</p></div><StatusPill product={p}/></div><p className="mt-8 text-3xl font-extrabold">{moneyValue(p.sellingPrice)}</p><p className="mt-2 text-sm text-[hsl(var(--muted-foreground))]">Profit {moneyValue(p.sellingPrice-p.purchasePrice)} per unit</p><div className="mt-7 grid grid-cols-2 gap-3">{[['Purchase price',moneyValue(p.purchasePrice)],['Current stock',`${p.quantity} units`],['Minimum stock',`${p.minStock} units`],['Warranty',p.warranty]].map(([l,v])=><div key={l} className="rounded-2xl bg-[hsl(var(--muted)/.62)] p-4"><p className="text-xs text-[hsl(var(--muted-foreground))]">{l}</p><p className="mt-2 text-sm font-bold">{v}</p></div>)}</div><div className="mt-7 flex gap-2"><Link href={`/inventory/${p.id}/edit`} className={`${buttonQuiet} flex-1`}><Edit3 className="h-4 w-4"/>Edit product</Link><Link href="/sales" className={`${buttonPrimary} flex-1`}><ShoppingCart className="h-4 w-4"/>Sell</Link></div></div></div><section className="mt-10"><p className={pageKicker}>Ledger</p><h2 className="mt-1 text-xl font-bold">Transaction history</h2><div className="mt-4 overflow-hidden rounded-2xl border border-[hsl(var(--border))] bg-[hsl(var(--card))]">{history.filter(h=>h.productId===p.id).map(h=><div key={h.id} className="grid gap-1 border-b px-5 py-4 sm:grid-cols-4"><span className="text-xs">{dateLabel(h.date)}</span><span className="text-xs font-bold">{h.type}</span><span className="text-sm font-semibold">{h.type==='SALE'?'-':'+'}{h.quantity}</span><span className="text-xs text-[hsl(var(--muted-foreground))]">{h.note}</span></div>)}</div></section></div>}

function AppRouter(){return <InventoryProvider><InventoryShell><ErrorBoundary><Switch><Route path="/" component={HomePage}/><Route path="/inventory" component={InventoryPage}/><Route path="/inventory/new" component={ProductFormPage}/><Route path="/inventory/:id/edit" component={ProductFormPage}/><Route path="/product/:id" component={ProductDetailScreen}/><Route path="/stock-history" component={HistoryPage}/><Route path="/purchases" component={PurchasesPage}/><Route path="/purchases/new" component={PurchaseFormPage}/><Route path="/sales" component={SalesPage}/><Route path="/customers" component={CustomersPage}/><Route path="/customers/new" component={CustomerFormPage}/><Route path="/customers/:id/edit" component={CustomerFormPage}/><Route path="/customers/:id" component={CustomerDetailPage}/><Route component={NotFound}/></Switch></ErrorBoundary></InventoryShell></InventoryProvider>}

function App(){return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter><AppRouter/></WouterRouter><Toaster/></TooltipProvider></QueryClientProvider>}
export default App;
